<script setup lang="ts">
import type { AdminAuditLogEntry, DesktopPluginCapability, DesktopPluginReport, DesktopPluginReviewDetail, DesktopPluginReviewMetrics, DesktopPluginReviewQueueItem } from "@password-detective/api-contract";
import { computed, onMounted, ref } from "vue";
import { useRouter } from "vue-router";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import PluginRunnerManagement from "../components/PluginRunnerManagement.vue";
import { listAdminAuditLogs } from "../services/auditLogs";
import { approvePluginVersion, deletePluginVersion, getPluginReview, getPluginReviewMetrics, listPluginReports, listPluginReviews, publishPluginVersion, rejectPluginVersion, resolvePluginReport, revokePluginVersion, rerunPluginStaticReview, yankPluginVersion } from "../services/pluginReviews";
import { useAdminAuthStore } from "../stores/auth";

const auth = useAdminAuthStore(); const router = useRouter();
const queue = ref<DesktopPluginReviewQueueItem[]>([]); const reports = ref<DesktopPluginReport[]>([]); const logs = ref<AdminAuditLogEntry[]>([]); const metrics = ref<DesktopPluginReviewMetrics | null>(null); const selected = ref<DesktopPluginReviewDetail | null>(null); const approvedCapabilities = ref<DesktopPluginCapability[]>([]); const note = ref("按人工审核策略检查通过。"); const remediationDays = ref(7); const error = ref(""); const success = ref(""); const busy = ref(false);
const canApprove = computed(() => selected.value?.status === "manual_review_ready");
const statusLabel = (status: string): string => ({ review_queued: "等待自动审核", auto_review_running: "自动审核中", auto_review_failed: "自动审核未通过", manual_review_ready: "待人工审核", approved: "已批准", published: "已发布", rejected: "已驳回", yanked: "已下架", revoked: "已撤销", submitted: "已提交" }[status] ?? status);
async function load(): Promise<void> { try { const [r, p, m, l] = await Promise.all([listPluginReviews(auth.accessToken), listPluginReports(auth.accessToken), getPluginReviewMetrics(auth.accessToken), listAdminAuditLogs({ page: 1, pageSize: 8 }, auth.accessToken)]); queue.value = r.items; reports.value = p.items; metrics.value = m; logs.value = l.items; } catch (e) { error.value = e instanceof Error ? e.message : "无法加载插件审核工作台"; } }
async function selectReview(item: DesktopPluginReviewQueueItem): Promise<void> { selected.value = await getPluginReview(auth.accessToken, item.version_id); approvedCapabilities.value = [...selected.value.requested_capabilities]; }
function toggleCapability(c: DesktopPluginCapability, checked: boolean | "indeterminate"): void { approvedCapabilities.value = checked === true ? [...new Set([...approvedCapabilities.value, c])] : approvedCapabilities.value.filter((x) => x !== c); }
async function run(action: "approve" | "reject" | "publish" | "yank" | "revoke"): Promise<void> { if (!selected.value) return; busy.value = true; try { const d = selected.value; selected.value = action === "approve" ? await approvePluginVersion(auth.accessToken, d, approvedCapabilities.value, note.value) : action === "reject" ? await rejectPluginVersion(auth.accessToken, d, note.value, remediationDays.value) : action === "publish" ? await publishPluginVersion(auth.accessToken, d) : action === "yank" ? await yankPluginVersion(auth.accessToken, d, note.value, remediationDays.value) : await revokePluginVersion(auth.accessToken, d, note.value); success.value = "插件审核状态已更新。"; await load(); } catch (e) { error.value = e instanceof Error ? e.message : "插件审核操作失败"; } finally { busy.value = false; } }
async function removeSelected(): Promise<void> { if (!selected.value) return; busy.value = true; try { await deletePluginVersion(auth.accessToken, selected.value.version_id); selected.value = null; success.value = "插件版本已删除。"; await load(); } catch (e) { error.value = e instanceof Error ? e.message : "插件删除失败"; } finally { busy.value = false; } }
async function rerun(): Promise<void> { if (!selected.value) return; busy.value = true; try { selected.value = await rerunPluginStaticReview(auth.accessToken, selected.value); await load(); } catch (e) { error.value = e instanceof Error ? e.message : "重新执行自动审核失败"; } finally { busy.value = false; } }
async function resolveReport(report: DesktopPluginReport): Promise<void> { busy.value = true; try { await resolvePluginReport(auth.accessToken, report, note.value); await load(); } finally { busy.value = false; } }
onMounted(load);
</script>

<template>
  <section class="space-y-6 pt-16 lg:pt-0"><header class="space-y-2"><p class="text-xs font-semibold text-primary">PLUGIN MARKETPLACE</p><h1 class="text-3xl font-semibold">插件商城管理</h1><p class="text-sm text-muted-foreground">审核权限差异、签名摘要、版本历史、发布状态与用户举报。</p></header><div v-if="error" class="rounded-md border border-destructive/50 bg-destructive/10 p-4 text-sm text-destructive">{{ error }}</div><div v-if="success" class="rounded-md border border-primary/40 bg-primary/10 p-4 text-sm">{{ success }}</div>
    <div class="grid gap-6 xl:grid-cols-[minmax(18rem,0.8fr)_minmax(0,1.4fr)]"><Card><CardHeader><CardTitle>审核队列</CardTitle><CardDescription>选择版本查看完整审核事实。</CardDescription></CardHeader><CardContent class="space-y-3"><Button v-for="item in queue" :key="item.version_id" variant="outline" class="h-auto w-full justify-between p-4 text-left" @click="selectReview(item)"><span><strong class="block">{{ item.plugin_name }} {{ item.semver }}</strong><small class="text-muted-foreground">{{ item.plugin_slug }}</small></span><Badge>{{ statusLabel(item.status) }}</Badge></Button><p v-if="queue.length === 0" class="text-sm text-muted-foreground">暂无待审核插件版本。</p></CardContent></Card>
      <Card><CardHeader><CardTitle>版本审核详情</CardTitle><CardDescription>批准权限必须是开发者申请权限的子集。</CardDescription></CardHeader><CardContent v-if="selected" class="space-y-5"><div class="flex flex-wrap gap-2"><Badge>{{ statusLabel(selected.status) }}</Badge><Badge variant="outline">{{ selected.semver }}</Badge><Badge variant="outline">{{ selected.risk_tier }}</Badge></div><p class="break-all text-xs text-muted-foreground">Manifest SHA-256：{{ selected.manifest_sha256 }}</p><div class="flex flex-wrap items-end gap-2 border-y py-4"><div class="space-y-2"><Label for="remediation-days">整改时间（天）</Label><Input id="remediation-days" v-model.number="remediationDays" type="number" min="1" max="30" class="w-24" /></div><Button v-if="['auto_review_failed','review_queued'].includes(selected.status)" size="sm" variant="outline" :disabled="busy" @click="rerun">重新执行自动审核</Button><Button size="sm" variant="destructive" :disabled="busy" @click="removeSelected">删除插件版本</Button><Button size="sm" variant="outline" @click="router.push(`/plugin-reviews/${selected.version_id}/source`)">打开源码审查</Button></div><div class="space-y-3 border-y py-4"><h3 class="font-medium">自动静态与供应链审核</h3><div v-for="runItem in selected.review_runs" :key="runItem.id" class="space-y-3 rounded-md border p-3"><div class="flex flex-wrap items-center gap-2"><Badge>{{ runItem.status }}</Badge><code class="text-xs">{{ runItem.policy_version }}</code><span class="text-xs text-muted-foreground">第 {{ runItem.attempt }} 次执行</span></div><p v-if="runItem.error_message" class="text-sm text-destructive">{{ runItem.error_message }}</p><div v-for="finding in runItem.findings" :key="finding.id" class="rounded-md bg-muted p-3 text-sm"><strong>{{ finding.title }}</strong><p class="text-muted-foreground">{{ finding.detail }}</p></div></div><p v-if="selected.review_runs.length === 0" class="text-sm text-muted-foreground">自动审核尚未开始。</p></div><fieldset class="space-y-3"><legend class="text-sm font-medium">批准权限</legend><div v-for="capability in selected.requested_capabilities" :key="capability" class="flex items-center gap-3"><Checkbox :id="`plugin-capability-${capability}`" :checked="approvedCapabilities.includes(capability)" @update:checked="toggleCapability(capability, $event)" /><Label :for="`plugin-capability-${capability}`"><code>{{ capability }}</code></Label></div></fieldset><div class="space-y-2"><Label for="plugin-review-note">审核意见或处置原因</Label><Textarea id="plugin-review-note" v-model="note" rows="3" /></div><div class="flex flex-wrap gap-2"><Button v-if="canApprove" :disabled="busy" @click="run('approve')">批准权限</Button><Button v-if="canApprove" variant="destructive" :disabled="busy" @click="run('reject')">驳回</Button><Button v-if="selected.status === 'approved'" :disabled="busy" @click="run('publish')">发布 stable</Button><Button v-if="selected.status === 'published'" variant="outline" :disabled="busy" @click="run('yank')">普通下架</Button><Button v-if="['approved','published','yanked'].includes(selected.status)" variant="destructive" :disabled="busy" @click="run('revoke')">紧急撤销</Button></div><div class="space-y-2 border-t pt-4"><h3 class="font-medium">不可变审核历史</h3><div class="max-h-48 space-y-2 overflow-y-auto pr-1"><div v-for="event in selected.events" :key="event.id" class="rounded-md bg-muted p-3 text-sm"><strong>{{ statusLabel(event.kind) }}</strong><p v-if="event.note" class="text-muted-foreground">{{ event.note }}</p></div></div></div></CardContent><CardContent v-else class="text-sm text-muted-foreground">从审核队列选择一个版本。</CardContent></Card></div>
    <Card><CardHeader><CardTitle>全局系统日志</CardTitle><CardDescription>最近的脱敏系统审计事件。</CardDescription></CardHeader><CardContent class="max-h-72 space-y-2 overflow-y-auto"><article v-for="log in logs" :key="log.id" class="rounded-md border p-3 text-sm"><div class="flex flex-wrap items-center gap-2"><Badge :variant="log.result === 'failure' ? 'destructive' : 'outline'">{{ log.result }}</Badge><code>{{ log.action }}</code><span class="text-xs text-muted-foreground">{{ log.created_at }}</span></div><p class="mt-1 text-xs text-muted-foreground">{{ log.target_type }} · {{ log.target_id || '无目标' }}</p></article><p v-if="logs.length === 0" class="text-sm text-muted-foreground">暂无系统日志。</p></CardContent></Card><Card><CardHeader><CardTitle>用户举报</CardTitle></CardHeader><CardContent class="space-y-3"><article v-for="report in reports" :key="report.id" class="flex items-center justify-between rounded-md border p-3"><span class="text-sm">{{ report.description }}</span><Button v-if="report.status !== 'resolved'" variant="outline" @click="resolveReport(report)">标记已处置</Button></article><p v-if="reports.length === 0" class="text-sm text-muted-foreground">暂无插件举报。</p></CardContent></Card><PluginRunnerManagement /><Card v-if="metrics"><CardHeader><CardTitle>审核运行指标</CardTitle></CardHeader><CardContent class="grid gap-3 sm:grid-cols-2"><p>待处理积压：{{ Object.values(metrics.queue_depth_by_architecture).reduce((sum, value) => sum + value, 0) }}</p><p>可用 Runner：{{ Object.values(metrics.runner_capacity_by_architecture).reduce((sum, value) => sum + value, 0) }}</p></CardContent></Card>
  </section>
</template>
